		rts
; ---------------------------------------------------------------------------

loc_AEA2:				; CODE XREF: ROM:0000AE9Aj
		btst	#0,AnimationStatus(a2) ; BIT 7	 10000000 - 80	 DMA
					; BIT 6	  01000000 - 40
					; BIT 5	  00100000 - 20
					; BIT 4	  00010000 - 10
					; BIT 3	  00001000 - 8
					; BIT 2	  00000100 - 4
					; BIT 1	  00000010 - 2
					; BIT 0	  00000001 - 1	set if animation script	needs updating
		beq.s	loc_AEDC
		clr.l	Screen_Y_Inertia(a2)
		bset	#7,ObjStatus1(a2) ; BIT	7   10000000 - 80   Obj	Active
					; BIT 6	  01000000 - 40	  Knockout Flag
					; BIT 5	  00100000 - 20	  Main Character hold Partner/Enemy
					; BIT 4	  00010000 - 10	  Partner/Enemy	hold Main Character
					; BIT 3	  00001000 - 8	  Attack flag
					; BIT 2	  00000100 - 4	  Hit flag
					; BIT 1	  00000010 - 2
					; BIT 0	  00000001 - 1	  0 = Hit from Left
					;			  1 = Hit from Right (used for setting breakable objects inertia)
		andi.w	#1,NextAnimation(a2)
		ori.w	#0,NextAnimation(a2)
		move.w	#2,ObjMode(a2)
		sf	ComboCountTimer(a2) ; timer used for combo attacks ie button presses
		tst.b	AttackChk(a2)	; 00 = sprite not touching object
					; 11 = sprite touching object
		bne.s	loc_AED2
		rts
; ---------------------------------------------------------------------------

loc_AED2:				; CODE XREF: ROM:0000AECEj
		sf	AttackChk(a2)	; 00 = sprite not touching object
